     7	W = Path(os.environ.get('E168_ROOT', '/lfs/skampere2/0/brando9/e168_attacks_11-04-2026'))
     8	sys.path.insert(0, str(W / 'scripts'))
     9	from replay_pipeline import ALLOWED
    10	PROJECT = Path('/lfs/skampere2/0/brando9/vb90_grading/lean_project')
    11	LEAN = subprocess.check_output(['elan', 'which', 'lean'], cwd=PROJECT, text=True).strip()
    12	LP = subprocess.check_output(['lake', 'env', 'printenv', 'LEAN_PATH'], cwd=PROJECT, text=True).strip().splitlines()[-1]
    13	ENV = os.environ.copy()
    14	ENV['LEAN_PATH'] = ':'.join([str(W / 'fixed_controls/base'), str(W / 'modules'), str(W / 'pilot'), LP])
    15	FORBIDDEN = re.compile(r'\b(sorry|admit|axiom|native_decide|unsafe|run_tac|elab|macro|command|IO|System|Lean|Oracle|set_option|initialize)\b|#|«|»')  # unchanged from the original
    16	
    17	def check(module, family, proof, directory):
    18	    directory = Path(directory); directory.mkdir(parents=True, exist_ok=True)
    19	    rec = {'module': module, 'family': family, 'proof_sha256': hashlib.sha256(proof.encode()).hexdigest(), 'accepted': False}
    20	    (directory / 'candidate.txt').write_text(proof)
    21	    if len(proof) > 100000 or FORBIDDEN.search(proof):
    22	        rec['status'] = 'forbidden_syntax'; return rec
    23	    nonce = secrets.token_hex(16)  # chosen after the candidate is fixed, never shown to it
    24	    source = (f'import Clean_{module}\nimport ProofOnly\nimport AttackSupport\nset_option maxHeartbeats 400000\nnamespace Candidate\n'
    25	              f'candidate result : Clean.{family}Goal := {json.dumps(proof, ensure_ascii=False)}\n#audit_nonce "{nonce}" Candidate.result\nend Candidate\n')
    26	    path = directory / 'Candidate.lean'; path.write_text(source)
    27	    cmd = [sys.executable, str(W / 'scripts/lean_runner.py'), '--lean-child', LEAN, '-R', str(W), str(path)]
    28	    t = time.monotonic()
    29	    try:
    30	        p = subprocess.run(cmd, cwd=PROJECT, env=ENV, capture_output=True, text=True, timeout=45); rc, s = p.returncode, p.stdout + p.stderr
    31	    except subprocess.TimeoutExpired as ex:
    32	        rc = 124; s = (ex.stdout or b'').decode(errors='replace') + '\nTIMEOUT'
    33	    (directory / 'compiler.log').write_text(s + f'\nexit {rc}\n')
    34	    hits = re.findall(r'AUDIT_' + nonce + r' (\S+) \[([^\]]*)\]', s)
    35	    ax = [x.strip() for x in hits[0][1].split(',') if x.strip()] if len(hits) == 1 and hits[0][0] == 'Candidate.result' else None
    36	    ok = rc == 0 and ax is not None and not (set(ax) - ALLOWED)
    37	    rec.update(compile_exit=rc, axioms={'Candidate.result': ax}, accepted=ok,
    38	               status='proved' if ok else ('timeout' if rc == 124 else ('no_valid_audit' if ax is None and rc == 0 else 'not_proved')),
    39	               wall_seconds=time.monotonic() - t)
    40	    return rec
