print("example security names:")
sec=[t for t in split_of if t.startswith('security_set')]
for t in sorted(sec)[:6]: print("  ",t, split_of[t][:2])
# family key: security -> (number, name stem) ignoring safe/vulnerabilities markers
def fam(t):
    set_,_,rest=t.partition('__')
    if set_=='security_set':
        m=re.search(r'__(\d+)_([a-z0-9]+?)(?:_safe)?$', rest)
        if m: return ('security', m.group(1), m.group(2))
        return ('security', rest)
    # generic: strip trailing _safe/_unsafe and heap_sort/heapsort normalisation
    r=rest.replace('heap_sort','heapsort')
    r=re.sub(r'_(safe|unsafe)$','',r)
    toks=re.split(r'_+',r)
    return (set_, toks[0] if toks[0] not in ('humaneval','security') else '_'.join(toks[:2]))
groups=collections.defaultdict(list)
for t,s in split_of.items(): groups[fam(t)].append((t,s))
multi=[(k,v) for k,v in groups.items() if len(v)>1]
print("families with >1 task:", len(multi), "; total families:", len(groups))
cross=[(k,v) for k,v in multi if len({s for _,s in v})>1]
print("families spanning >1 split:", len(cross))
test_leak=sorted({t for k,v in cross for t,s in v if s=='test' and any(s2!='test' for _,s2 in v)})
print("test tasks sharing a family with a train/validation task:", len(test_leak), "/ 128")
for k,v in sorted(cross, key=str)[:40]:
    print("  ",k, [(t.split('__',1)[1][-45:], s[:2]) for t,s in v])
